function describe(node, depth) {
  depth = depth || 0;
  const pad = ' '.repeat(depth*2);
  let s = pad + node.id + ' ' + node.type + ' ' + JSON.stringify(node.name);
  const extra = [];
  if (node.type==='COMPONENT'||node.type==='COMPONENT_SET') extra.push('componentId='+node.id);
  if (node.type==='INSTANCE') extra.push('main='+ (node.mainComponent? node.mainComponent.id:'?'));
  if (node.type==='RECTANGLE') extra.push('fills='+JSON.stringify(node.fills).slice(0,80));
  if (node.fills && node.fills[0] && (node.fills[0].type==='IMAGE')) extra.push('IMG');
  if (node.type==='TEXT') extra.push('chars='+JSON.stringify(node.characters));
  if (extra.length) s += ' ['+extra.join(' | ')+']';
  return s;
}
