  label.fills=[{type:'SOLID',color:{r:1,g:1,b:1}}]; label.x=(335-label.width)/2; label.y=(50-label.height)/2;
  primBtn.appendChild(label);
  comps.appendChild(primBtn);

  // text field
  const tf=figma.createComponent(); tf.name='TextField'; tf.resize(335,52);
  const tbg=figma.createRectangle(); tbg.resize(335,52); tbg.fills=[{type:'SOLID',color:CARD}]; tbg.cornerRadius=26; tbg.strokes=[{type:'SOLID',color:LINE}];
  tf.appendChild(tbg);
  const ph=figma.createText(); ph.characters='Placeholder';
  ph.fontName={family:'DM Sans',style:'Regular'}; ph.fontSize=15; ph.fills=[{type:'SOLID',color:SUB}]; ph.x=48; ph.y=(52-ph.height)/2;
