    t.x=0; t.y=0;
    btn.appendChild(rect); btn.appendChild(t);
    // center text
    t.resize? t.resize(t.width,t.height):null;
    const tw = t.width;
    t.x=(335-tw)/2; t.y=(50-t.height)/2;
    comp.appendChild(btn);

    // Tab Bar component
    const tab = figma.createComponent();
    tab.name='Tab Bar'; tab.resize(375, 72);
    tab.fills=[{type:'SOLID',color:{r:1,g:1,b:1}}];
    const labels=['Store','Rewards','Orders'];
    const xpos=[42,187,332];
    const ml = ws.children.find(c=>c.name==='Media Library');
    const storeI=ml.children.find(c=>c.name==='Icon_Tab_Store_M');
    const rewI=ml.children.find(c=>c.name==='Icon_Tab_Rewards_M');
    const ordI=ml.children.find(c=>c.name==='Icon_Tab_Orders_M');
    const icons={Store:storeI, Rewards:rewI, Orders:ordI};
    labels.forEach((lab,i)=>{
      // icon
      if(icons[lab]){
        const inst = icons[lab].createInstance();
        inst.x = xpos[i]; inst.y=8;
        // set size
        inst.resizeWithin(22,22);
        // recolor to gray
        try{ if(inst.fills){ inst.fills = inst.fills.map(f=>({...f, color:{r:0.42,g:0.47,b:0.52}})); } }catch(e){}
        tab.appendChild(inst);
        // label
        const lt=figma.createText();
        lt.fontName={family:'Poppins',style:'Medium'}; lt.fontSize=10;
        lt.characters=lab; lt.fills=[{type:'SOLID',color:{r:0.42,g:0.47,b:0.52}}];
        lt.x=xpos[i]-12; lt.y=36;
        tab.appendChild(lt);
      }
    });
    comp.appendChild(tab);
  }catch(e){ /* swallow to persist */ }
}
