(() => {
  const out = [];
  const MAXN = 200;
  let count = 0;
  function walk(n, depth){
    if(count >= MAXN) return;
    count++;
    out.push('  '.repeat(depth) + n.type + ':' + n.name + ':' + n.id);
    if(n.children && depth < 3){ n.children.forEach(c=>walk(c, depth+1)); }
  }
  figma.root.children.forEach(p=>walk(p,0));
  throw new Error('TREE(trunc '+MAXN+')\n'+out.join('\n'));
})();

