(() => {
  const ws = figma.root.children.find(p=>p.type==='PAGE' && p.name==='03 · Workspace');
  // collect all frames and their ids recursively (limited depth)
  const out=[];
  function walk(n,d){
    if(d>2) return;
    if(n.type==='FRAME') out.push(n.id+':'+n.name);
    (n.children||[]).forEach(c=>walk(c,d+1));
  }
  ws.children.forEach(c=>walk(c,0));
  throw new Error(out.join('\n'));
})();

